template <class T>
concept ShippingPolicy = requires (const T& policy, const Parcel& parcel) {
    { policy.quoteFor(parcel) } -> std::convertible_to<Money>;
};

// the requirement is part of the interface: callers read the concept, not the body
template <ShippingPolicy Policy>
Money shipFor(const Policy& policy, const Parcel& parcel);
